'use client';

import { useState } from 'react';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

// Sample products to compare
const PRODUCTS: Product[] = [
  { id: '1', name: 'Premium Headphones', price: 299.99, category: 'Electronics', rating: 4.5, reviews: 1250, inStock: true },
  { id: '2', name: 'Wireless Earbuds', price: 149.99, category: 'Electronics', rating: 4.2, reviews: 3420, inStock: true },
  { id: '3', name: 'Studio Monitor', price: 449.99, category: 'Electronics', rating: 4.8, reviews: 567, inStock: false },
  { id: '4', name: 'Portable Speaker', price: 79.99, category: 'Electronics', rating: 4.0, reviews: 2100, inStock: true },
  { id: '5', name: 'Noise Canceling Pro', price: 379.99, category: 'Electronics', rating: 4.7, reviews: 890, inStock: true },
];

// Native implementations replacing lodash
const sortBy = <T>(arr: T[], key: keyof T): T[] => {
  return [...arr].sort((a, b) => {
    const aVal = a[key];
    const bVal = b[key];
    if (typeof aVal === 'number' && typeof bVal === 'number') {
      return aVal - bVal;
    }
    return String(aVal).localeCompare(String(bVal));
  });
};

const meanBy = (arr: Product[], key: keyof Product): number => {
  const sum = arr.reduce((acc, item) => acc + Number(item[key]), 0);
  return sum / arr.length;
};

const sumBy = (arr: Product[], key: keyof Product): number => {
  return arr.reduce((acc, item) => acc + Number(item[key]), 0);
};

const maxBy = (arr: Product[], key: keyof Product): Product | undefined => {
  return arr.reduce((max, item) => {
    return Number(item[key]) > Number(max?.[key] || -Infinity) ? item : max;
  }, undefined as Product | undefined);
};

const minBy = (arr: Product[], key: keyof Product): Product | undefined => {
  return arr.reduce((min, item) => {
    return Number(item[key]) < Number(min?.[key] || Infinity) ? item : min;
  }, undefined as Product | undefined);
};

// Native implementations replacing mathjs
const mean = (arr: number[]): number => arr.reduce((a, b) => a + b, 0) / arr.length;

const median = (arr: number[]): number => {
  const sorted = [...arr].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];
};

const std = (arr: number[]): number => {
  const avg = mean(arr);
  const squareDiffs = arr.map(value => Math.pow(value - avg, 2));
  return Math.sqrt(mean(squareDiffs));
};

const variance = (arr: number[]): number => {
  const avg = mean(arr);
  return arr.reduce((acc, val) => acc + Math.pow(val - avg, 2), 0) / arr.length;
};

const quantileSeq = (arr: number[], q: number): number => {
  const sorted = [...arr].sort((a, b) => a - b);
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  return sorted[base + 1] !== undefined ? sorted[base] + rest * (sorted[base + 1] - sorted[base]) : sorted[base];
};

function ComparisonTable({ products }: { products: Product[] }) {
  // Using native functions instead of lodash
  const sorted = sortBy(products, 'price');
  const avgPrice = meanBy(products, 'price');
  const totalReviews = sumBy(products, 'reviews');
  const bestRated = maxBy(products, 'rating');
  const cheapest = minBy(products, 'price');

