  rating: number;
  reviews: number;
  inStock: boolean;
}

// Sample products to compare
const PRODUCTS: Product[] = [
  { id: '1', name: 'Premium Headphones', price: 299.99, category: 'Electronics', rating: 4.5, reviews: 1250, inStock: true },
  { id: '2', name: 'Wireless Earbuds', price: 149.99, category: 'Electronics', rating: 4.2, reviews: 3420, inStock: true },
  { id: '3', name: 'Studio Monitor', price: 449.99, category: 'Electronics', rating: 4.8, reviews: 567, inStock: false },
  { id: '4', name: 'Portable Speaker', price: 79.99, category: 'Electronics', rating: 4.0, reviews: 2100, inStock: true },
  { id: '5', name: 'Noise Canceling Pro', price: 379.99, category: 'Electronics', rating: 4.7, reviews: 890, inStock: true },
];

// Native implementations replacing lodash - using explicit typing instead of generics to avoid JSX conflicts
const sortByProducts = (arr: Product[], key: keyof Product): Product[] => {
  return [...arr].sort((a, b) => {
    const aVal = a[key];
    const bVal = b[key];
    if (typeof aVal === 'number' && typeof bVal === 'number') {
      return aVal - bVal;
    }
    return String(aVal).localeCompare(String(bVal));
  });
};

const meanBy = (arr: Product[], key: keyof Product): number => {
  const sum = arr.reduce((acc, item) => acc + Number(item[key]), 0);
  return sum / arr.length;
};

const sumBy = (arr: Product[], key: keyof Product): number => {
  return arr.reduce((acc, item) => acc + Number(item[key]), 0);
};

const maxBy = (arr: Product[], key: keyof Product): Product | undefined => {
  return arr.reduce((max, item) => {
    return Number(item[key]) > Number(max?.[key] || -Infinity) ? item : max;
  }, undefined as Product | undefined);
};

const minBy = (arr: Product[], key: keyof Product): Product | undefined => {
  return arr.reduce((min, item) => {
    return Number(item[key]) < Number(min?.[key] || Infinity) ? item : min;
  }, undefined as Product | undefined);
};

// Native implementations replacing mathjs
